import { Table, ReferenceColumn } from '../../db'

export const sys_ws_query_parameter_map = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    display: 'web_service_query_parameter',
    extends: 'sys_metadata',
    label: 'Scripted REST Query Parameter Association',
    name: 'sys_ws_query_parameter_map',
    schema: {
        web_service_query_parameter: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The query parameter to associate with the resource',
                    label: 'API query parameter',
                    plural: 'API query parameters',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_ws_query_parameter',
            referenceQual:
                "javascript:'web_service_definition=' + current.web_service_operation.web_service_definition",
        }),
        web_service_operation: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The resource to associate with the query parameter',
                    label: 'API resource',
                    plural: 'API resources',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_ws_operation',
        }),
    },
    textIndex: true,
})
